package com.retail.inventory.service.impl;
import com.retail.inventory.dto.request.*; import com.retail.inventory.dto.response.*; import com.retail.inventory.entity.*; import com.retail.inventory.entity.enums.*; import com.retail.inventory.exception.*; import com.retail.inventory.repository.*; import com.retail.inventory.service.OrderService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class OrderServiceImpl implements OrderService { private final OrderRepository orders;private final ProductRepository products;private final WarehouseRepository warehouses;private final SupplierRepository suppliers;private final InventoryRepository inventory;private final StockTransactionRepository transactions;
 public Page<OrderResponse> findAll(String q,OrderStatus s,LocalDate f,LocalDate t,Pageable p){return orders.search(norm(q),s,f,t,p).map(this::response);} public OrderResponse findById(Long id){return response(order(id));} public List<OrderItemResponse> items(Long id){return response(order(id)).getItems();}
 @Transactional public OrderResponse create(CreateOrderRequest r){ Warehouse w=warehouses.findById(r.getWarehouseId()).orElseThrow(()->new ResourceNotFoundException("Warehouse","id",r.getWarehouseId())); if(r.getOrderType()==OrderType.PURCHASE_ORDER&&r.getSupplierId()==null)throw new BadRequestException("Purchase orders require a supplier"); Supplier s=r.getSupplierId()==null?null:suppliers.findById(r.getSupplierId()).orElseThrow(()->new ResourceNotFoundException("Supplier","id",r.getSupplierId())); Set<Long> ids=new HashSet<>(); Order o=new Order();o.setOrderNumber((r.getOrderType()==OrderType.PURCHASE_ORDER?"PO-":"SO-")+UUID.randomUUID());o.setOrderType(r.getOrderType());o.setWarehouse(w);o.setSupplier(s);o.setCustomerName(r.getCustomerName());o.setCustomerEmail(r.getCustomerEmail());o.setStatus(OrderStatus.DRAFT);o.setOrderDate(r.getOrderDate()==null?LocalDate.now():r.getOrderDate());o.setExpectedDeliveryDate(r.getExpectedDeliveryDate());o.setNotes(r.getNotes());o.setTaxAmount(zero(r.getTaxAmount()));o.setShippingAmount(zero(r.getShippingAmount())); BigDecimal total=BigDecimal.ZERO; for(OrderItemRequest x:r.getItems()){if(!ids.add(x.getProductId()))throw new BadRequestException("Duplicate product line items are not allowed");Product p=products.findById(x.getProductId()).orElseThrow(()->new ResourceNotFoundException("Product","id",x.getProductId()));BigDecimal sub=x.getUnitPrice().multiply(BigDecimal.valueOf(x.getQuantity()));OrderItem i=OrderItem.builder().product(p).quantityOrdered(x.getQuantity()).unitPrice(x.getUnitPrice()).subtotal(sub).build();o.addItem(i);total=total.add(sub);}o.setTotalAmount(total.add(o.getTaxAmount()).add(o.getShippingAmount()));return response(orders.save(o)); }
 @Transactional public OrderResponse updateStatus(Long id,OrderStatusUpdateRequest r){Order o=order(id);if(!valid(o.getStatus(),r.getStatus()))throw new BadRequestException("Invalid order status transition");if(o.getOrderType()==OrderType.SALES_ORDER&&r.getStatus()==OrderStatus.CONFIRMED)reserve(o);if(o.getOrderType()==OrderType.SALES_ORDER&&r.getStatus()==OrderStatus.SHIPPED)dispatch(o);if(o.getOrderType()==OrderType.PURCHASE_ORDER&&r.getStatus()==OrderStatus.DELIVERED)receive(o);o.setStatus(r.getStatus());if(r.getNotes()!=null)o.setNotes(r.getNotes());return response(orders.save(o));}
 @Transactional public OrderResponse cancel(Long id){Order o=order(id);if(o.getStatus()==OrderStatus.CANCELLED)throw new BadRequestException("Order is already cancelled");if(o.getStatus()==OrderStatus.SHIPPED||o.getStatus()==OrderStatus.DELIVERED||o.getStatus()==OrderStatus.COMPLETED)throw new BadRequestException("Fulfilled orders cannot be cancelled");if(o.getOrderType()==OrderType.SALES_ORDER&&(o.getStatus()==OrderStatus.CONFIRMED||o.getStatus()==OrderStatus.PROCESSING))release(o);o.setStatus(OrderStatus.CANCELLED);return response(orders.save(o));}
 private void reserve(Order o){for(OrderItem i:sorted(o)){Inventory v=locked(i,o);if(v.getQuantityAvailable()<i.getQuantityOrdered())throw new InsufficientStockException("Insufficient stock for "+i.getProduct().getSku());v.setQuantityReserved(v.getQuantityReserved()+i.getQuantityOrdered());inventory.save(v);tx(v,TransactionType.STOCK_ADJUSTMENT,0,v.getQuantityOnHand(),v.getQuantityOnHand(),"Reserved for "+o.getOrderNumber());}}
 private void dispatch(Order o){for(OrderItem i:sorted(o)){Inventory v=locked(i,o);if(v.getQuantityReserved()<i.getQuantityOrdered())throw new InsufficientStockException("Reserved inventory is unavailable");int before=v.getQuantityOnHand();v.setQuantityReserved(v.getQuantityReserved()-i.getQuantityOrdered());v.setQuantityOnHand(before-i.getQuantityOrdered());inventory.save(v);tx(v,TransactionType.SALES_DISPATCH,-i.getQuantityOrdered(),before,v.getQuantityOnHand(),"Dispatched for "+o.getOrderNumber());}}
 private void release(Order o){for(OrderItem i:sorted(o)){Inventory v=locked(i,o);v.setQuantityReserved(Math.max(0,v.getQuantityReserved()-i.getQuantityOrdered()));inventory.save(v);}}
 private void receive(Order o){for(OrderItem i:sorted(o)){Inventory v=inventory.findByProductIdAndWarehouseIdForUpdate(i.getProduct().getId(),o.getWarehouse().getId()).orElseGet(()->inventory.save(Inventory.builder().product(i.getProduct()).warehouse(o.getWarehouse()).quantityOnHand(0).quantityReserved(0).build()));int before=v.getQuantityOnHand();v.setQuantityOnHand(before+i.getQuantityOrdered());i.setQuantityReceived(i.getQuantityOrdered());inventory.save(v);tx(v,TransactionType.PURCHASE_RECEIPT,i.getQuantityOrdered(),before,v.getQuantityOnHand(),"Received for "+o.getOrderNumber());}}
 private Inventory locked(OrderItem i,Order o){return inventory.findByProductIdAndWarehouseIdForUpdate(i.getProduct().getId(),o.getWarehouse().getId()).orElseThrow(()->new InsufficientStockException("No inventory record for "+i.getProduct().getSku()));} private List<OrderItem> sorted(Order o){return o.getItems().stream().sorted(Comparator.comparing(x->x.getProduct().getId())).toList();} private void tx(Inventory v,TransactionType type,int qty,int before,int after,String note){transactions.save(StockTransaction.builder().transactionCode("TX-"+UUID.randomUUID()).product(v.getProduct()).warehouse(v.getWarehouse()).transactionType(type).quantity(qty).previousQuantity(before).newQuantity(after).notes(note).referenceNumber(null).performedBy("SYSTEM").build());}
 private boolean valid(OrderStatus a,OrderStatus b){return switch(a){case DRAFT->b==OrderStatus.PENDING||b==OrderStatus.CANCELLED;case PENDING->b==OrderStatus.CONFIRMED||b==OrderStatus.CANCELLED;case CONFIRMED,APPROVED->b==OrderStatus.PROCESSING||b==OrderStatus.CANCELLED;case PROCESSING->b==OrderStatus.SHIPPED||b==OrderStatus.CANCELLED;case SHIPPED->b==OrderStatus.DELIVERED;default->false;};} private Order order(Long id){return orders.findByIdWithDetails(id).orElseThrow(()->new ResourceNotFoundException("Order","id",id));} private BigDecimal zero(BigDecimal b){return b==null?BigDecimal.ZERO:b;} private String norm(String s){return s==null?null:s.trim();}
 private OrderResponse response(Order o){return OrderResponse.builder().id(o.getId()).orderNumber(o.getOrderNumber()).orderType(o.getOrderType()).status(o.getStatus()).warehouseId(o.getWarehouse().getId()).warehouseCode(o.getWarehouse().getWarehouseCode()).supplierId(o.getSupplier()==null?null:o.getSupplier().getId()).supplierName(o.getSupplier()==null?null:o.getSupplier().getCompanyName()).totalAmount(o.getTotalAmount()).taxAmount(o.getTaxAmount()).shippingAmount(o.getShippingAmount()).orderDate(o.getOrderDate()).expectedDeliveryDate(o.getExpectedDeliveryDate()).notes(o.getNotes()).items(o.getItems().stream().map(i->OrderItemResponse.builder().id(i.getId()).productId(i.getProduct().getId()).sku(i.getProduct().getSku()).name(i.getProduct().getName()).quantityOrdered(i.getQuantityOrdered()).quantityReceived(i.getQuantityReceived()).unitPrice(i.getUnitPrice()).subtotal(i.getSubtotal()).build()).toList()).build();}}
